CREATE FUNCTION public.update_player_stats() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    current_match_closing_odds DECIMAL(10,2);
    bet_clv DECIMAL(10,4);
    bet_profit DECIMAL(10,2);
BEGIN
    -- 1. Βρίσκουμε την απόδοση κλεισίματος του αγώνα
    SELECT closing_odds_1 INTO current_match_closing_odds 
    FROM matches WHERE match_id = NEW.match_id;

    -- 2. Υπολογίζουμε το CLV του συγκεκριμένου στοιχήματος
    bet_clv := NEW.odds_placed - current_match_closing_odds;

    -- 3. Υπολογίζουμε το κέρδος/ζημιά (αν κέρδισε: (stake*odds)-stake, αν έχασε: -stake)
    IF NEW.payout > 0 THEN
        bet_profit := NEW.payout - NEW.stake;
    ELSE
        bet_profit := -NEW.stake;
    END IF;

    -- 4. Ενημερώνουμε (ή δημιουργούμε) τα στατιστικά του παίκτη
    VALUES (NEW.user_id, 1, bet_profit, bet_clv)
    ON CONFLICT (user_id) DO UPDATE SET
        total_bets = player_stats.total_bets + 1,
        net_profit = player_stats.net_profit + EXCLUDED.net_profit,
        avg_clv = (player_stats.avg_clv * player_stats.total_bets + EXCLUDED.avg_clv) / (player_stats.total_bets + 1);

    RETURN NEW;
END;
$$;


